namespace SuikodenRandomizer.Core.Recording;

public sealed class CaptureCharacter
{
    public int Id { get; }
    public string Name { get; }
    public string Requirement { get; }
    public string SourceRole { get; }
    public int SourceLine { get; }
    public CaptureCharacter(int id, string name, string requirement, string sourceRole, int sourceLine)
    { Id = id; Name = name; Requirement = requirement; SourceRole = sourceRole; SourceLine = sourceLine; }
}

